    if (name == "Battle Healer") return 4;
    if (name == "Battle Ram") return 1;
    if (name == "Berserker") return 2;
    if (name == "Bomb Tower") return 5;
    if (name == "Bomber") return 2;
    if (name == "Boss Bandit") return 4;
    if (name == "Bowler") return 5;
    if (name == "Cannon") return 9;
    if (name == "Cannon Cart") return 5;
    if (name == "Dark Prince") return 4;
    if (name == "Dart Goblin") return 4;
    if (name == "Electro Dragon") return 5;
    if (name == "Electro Giant") return 10;
    if (name == "Electro Spirit") return 2;
    if (name == "Electro Wizard") return 6;
    if (name == "Elite Barbarians") return 5;
    if (name == "Elixir Collector") return -1;
    if (name == "Elixir Golem") return 8;
    if (name == "Executioner") return 5;
    if (name == "Fire Spirit") return 2;
    if (name == "Firecracker") return 7;
    if (name == "Fisherman") return 1;
    if (name == "Flying Machine") return 5;
    if (name == "Furnace") return 5;
    if (name == "Giant") return 5;
    if (name == "Giant Skeleton") return 3;
